{
  "title": "夜探秘籍",
  "scene": "你是一位江湖小侠，为了解开门派内一场恩怨的真相，决定夜探藏书楼寻找线索。月色朦胧，藏书楼下有两位守卫正在交谈，隐约听到他们提到今晚掌门会亲自巡视藏书楼。楼门紧闭，但窗缝间透出微弱的烛光，似乎有人在内。楼旁有一棵老树，枝叶茂盛，几乎可以触碰到窗户。藏书楼外围的墙上，刻着一些奇怪的符号，像是某种暗号。",
  "goal": "潜入藏书楼，找到并带走秘籍",
  "clue": "藏书楼外围的墙上刻着奇怪的符号",
  "choices": [
    {
      "id": "A",
      "text": "轻功跃窗而入",
      "outcome": "你施展轻功，悄无声息地从窗外跃入藏书楼。屋内有一名老者正在翻阅书籍，他突然抬头，但你迅速藏身于书架后，成功避过。你找到了秘籍，但老者的警觉使得你在取书时动作更加小心，浪费了一些时间。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "解暗号开侧门",
      "outcome": "你仔细研究墙上的符号，发现它们排列成掌门平日里喜欢的诗句。用这组暗号排列的顺序轻敲侧门，门悄然打开。你顺利进入藏书楼，找到了秘籍，且没有被任何人发现。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "硬闯正门",
      "outcome": "你决定直接硬闯正门，但守卫立刻发出警报，引来了更多人。虽然你武功不弱，但寡不敌众，最终被制服。不过守卫看在你是本门弟子的份上，只是将你暂时关押，未加严惩。",
      "result": "fail",
      "next": "retry"
    }
  ]
}
